"""Actual React error origin and recovery; all service/storage replies are controlled."""
import argparse,json,re
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
p=argparse.ArgumentParser();p.add_argument('--url',required=True);p.add_argument('--report',required=True,type=Path);args=p.parse_args();checks=[]
source='Hi, could you send the schedule by Friday? Please bring the draft budget.'
with sync_playwright() as pw:
 b=pw.chromium.launch(headless=True,channel='msedge')
 try:
  page=b.new_page(viewport={'width':1240,'height':800});page.set_default_timeout(5000)
  page.add_init_script("""localStorage.setItem('ol.locale','en');sessionStorage.setItem('ol.providerSetupPromptDeferredThisSession','1');window.__calls=[];window.__scenario='malformed';window.__fixture=(cmd,args,mock)=>{window.__calls.push({cmd,args});if(cmd==='get_style_text_trial_readiness')return {available:true,requiresTextService:true,textServiceConfigured:true};if(cmd==='try_style_pack_text')return {packId:args.stylePackId,packName:'Light polish',outputText:args.rawText,usedTextService:true,elapsedMs:932};if(cmd==='suggest_polite_text_edits'){const s=window.__scenario;if(s==='request')return Promise.reject(Error('test transport interrupted'));if(s==='native-rejected')return Promise.reject(Error('polite_edits_invalid_response'));if(s==='late')return new Promise(resolve=>window.__finish=()=>resolve({proposalJson:'not json',elapsedMs:1028}));const replies={malformed:'not json',shape:'{"changes":[]}',missing:'{"edits":[{"old":"not in the source","new":"please"}]}',long:JSON.stringify({edits:[{old:'x'.repeat(81),new:'please'}]})};return {proposalJson:replies[s],elapsedMs:1028};}return mock();};""")
  def fixture(route):
   response=route.fetch();s=response.text();old='if (!isTauri) {\n    return mock();\n  }';assert s.count(old)==1;route.fulfill(response=response,body=s.replace(old,'if (!isTauri) {\n    return window.__fixture(cmd,args,mock);\n  }',1))
  page.route(re.compile(r'/src/lib/ipc\.ts(?:\?.*)?$'),fixture);page.goto(args.url,wait_until='networkidle');page.get_by_role('button',name='Try typed text',exact=True).click();trial=page.locator('dialog').last;trial.get_by_role('combobox').select_option('builtin.light');trial.get_by_label('Your text',exact=True).fill(source);trial.get_by_role('button',name=re.compile(r'^(?:Try this text|Process text|Generate draft|Preparing…)$'),exact=True).click();editor=trial.get_by_label('Result text',exact=True);expect(editor).to_have_value(source);trial.get_by_role('button',name='Wording options',exact=True).click();panel=trial.get_by_role('region',name='Request wording',exact=True);request=panel.get_by_role('button',name='Ask text service for alternatives',exact=True)
  for scenario in ['malformed','shape','missing','long','native-rejected']:
   page.evaluate('(s)=>window.__scenario=s',scenario);request.click();alert=panel.get_by_role('alert');expect(alert).to_contain_text('The text service replied');expect(alert).to_contain_text('could not be used safely');expect(alert).not_to_contain_text('Check the text service');expect(editor).to_have_value(source);expect(panel.get_by_role('button',name='Use this wording',exact=True).first).to_be_enabled();expect(panel.get_by_role('checkbox')).to_have_count(0)
  checks.append('after a successful main polish, malformed/unsupported/missing-span/overlong and native rejected replies are labelled received-but-unusable; no account-failure claim, original and local actions kept, unsafe edits never selectable')
  page.evaluate("window.__scenario='request'");request.click();expect(panel.get_by_role('alert')).to_contain_text('The request did not complete');expect(panel.get_by_role('alert')).not_to_contain_text('service replied');expect(editor).to_have_value(source);checks.append('transport rejection reports incomplete request, not malformed response or invented quota/configuration failure')
  page.evaluate("window.__scenario='late'");request.click();page.wait_for_function('!!window.__finish');editor.fill(source+' New sentence.');page.evaluate('window.__finish()');expect(request).to_be_enabled();expect(panel.get_by_role('alert')).to_have_count(0);expect(editor).to_have_value(source+' New sentence.');checks.append('late failed review belongs to its original text and cannot show a misleading failure against a newer draft')
  page.evaluate("window.__scenario='malformed'");request.click();expect(panel.get_by_role('alert')).to_contain_text('service replied');panel.get_by_role('button',name='Use this wording',exact=True).first.click();expect(panel.get_by_role('alert')).to_have_count(0);expect(editor).not_to_have_value(source+' New sentence.');expected=editor.input_value();trial.get_by_role('button',name='Save draft',exact=True).click();expect(trial.get_by_role('button',name='Saved draft',exact=True)).to_be_disabled();calls=page.evaluate('window.__calls');save=[x['args'] for x in calls if x['cmd']=='save_text_draft'][-1];assert save['original']==source and save['text']==expected;assert sum(x['cmd']=='suggest_polite_text_edits' for x in calls)==8;assert not any(x['cmd'] in {'set_credential','set_active_llm_provider','update_preferences','start_dictation','copy_style_trial_result','insert_style_trial_result'} for x in calls);checks.append('explicit local recovery clears the old error and saves accepted wording with original; no automatic retry, credential write, copy, insertion or recording')
  args.report.parent.mkdir(parents=True,exist_ok=True);args.report.write_text(json.dumps({'passed':True,'scope':'Actual React with fake service/storage; not native live-cloud/customer proof.','checks':checks},ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':True,'checks':checks}))
 finally:b.close()
